def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/environment/input/water-body-testing-*.csv')
    dfs = []
    for f in sorted(files):
        dfs.append(pd.read_csv(f))
    return pd.concat(dfs, ignore_index=True)

def process(calculate_yearly_rates) -> pd.DataFrame:
    avg = calculate_yearly_rates['exceedance_rate'].mean()
    return pd.DataFrame({'average_exceedance_rate': [round(avg, 2)]})

def process(calculate_yearly_rates, average_rate) -> pd.DataFrame:
    avg_val = average_rate['average_exceedance_rate'].iloc[0]
    result = calculate_yearly_rates[calculate_yearly_rates['exceedance_rate'] > avg_val]['Year'].sort_values()
    return pd.DataFrame({'Year': result.values})
